{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid closely related to the query's polyene chain, has an absolute oral bioavailability of approximately 60% (range 36–95%) after a 50 mg oral dose with food versus IV.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a lipophilic retinoid analog, has an absolute oral bioavailability of about 40% versus IV in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin (13-cis-retinoic acid) has a systemic bioavailability of 40% at a dosage of 1 mg/kg/day.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "All-trans retinoic acid oral bioavailability is estimated at approximately 50% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure with the query, has an absolute oral bioavailability of about 82% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis-retinoic acid is reported to have low absolute bioavailability with significant gastrointestinal degradation, a qualitative contradictory observation.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "All-trans retinoic acid in its current oral formulation is described as having low and erratic oral bioavailability, a qualitative contradictory observation.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoid amide (fenretinide-like). Quantitative absolute bioavailability values for close retinoid analogs—acitretin ~60%, etretinate ~40%, isotretinoin ~40%, and ATRA ~50%—all exceed the F ≥ 20% threshold. Qualitative reports of low/erratic retinoid bioavailability are outweighed by these quantitative measurements, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No human intravenous-comparator study for fenretinide-like retinamide is available in the evidence.",
    "The effect of the p-hydroxyanilide amide moiety on first-pass metabolism and absorption relative to retinoid acids is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

